# Lane currency check (item 27: session-start currency gate). `startupCheck` has NO `block` value --
# the never-blocks guarantee is structural, not a policy the handler is trusted to keep.
DEFAULT_LANE_STATUS = {
    "startupCheck": "report",
    # Schema max is 15 and the SessionStart host timeout is 25, so the host can never kill the hook
    # before the collector reports UNVERIFIED.
    "fetchTimeoutSeconds": 8,
    "maxAgeMinutes": 60,
    "integrationBranch": "",  # "" -> fall back to latestCode.base
    "statusFile": ".ai-work/LANE_STATUS.json",
    "claimSource": "",  # "" -> claim lookup is NOT performed (claim_state="not-checked")
}
LANE_STATUS_MAX_FETCH_TIMEOUT_SECONDS = 15
# One shared budget for ALL collection probes (fetch + every local git call), sized below
# SESSION_START_LANE_STATUS_HOOK_TIMEOUT (25) so the report always gets printed.
LANE_STATUS_COLLECTION_BUDGET_SECONDS = 18
# Bound the claim enumeration so a huge or slow claimSource cannot burn the budget.
LANE_STATUS_MAX_CLAIM_ENTRIES = 2000
# `redact_secrets` masks token SHAPES; it does not touch URL userinfo, and git echoes exactly that
# form on a failed authenticated fetch.
LANE_STATUS_URL_USERINFO_RE = re.compile(r"([a-zA-Z][a-zA-Z0-9+.-]*://)[^/@\s]*@")
LANE_STATUS_UNUSABLE_REMOTE = "<unusable>"

PRODUCT_DEV_MODE_SCHEMA = "tautline-product-dev-mode/v1"
# Fixed default TTL, stamped into expiresAt at write time so a forgotten `on` auto-expires and
# cannot bleed into a later dev-agent session. No adapter override in scope (all-or-nothing).
PRODUCT_DEV_MODE_DEFAULT_TTL_MINUTES = 240


# ---------------------------------------------------------------------------
# Fleet Governor: machine-local lease coordination across worktrees (v1).
# State lives in <git-common-dir>/tautline-fleet so every worktree of a repo
# shares it with zero configuration. Guard posture is deliberately fail-open:
# a coordination aid must never strand a lane on bad state.
# ---------------------------------------------------------------------------

FLEET_LEASE_SCHEMA = "tautline-fleet-lease/v1"
FLEET_ENFORCEMENT_CHOICES = ("block", "advise", "observe")
DEFAULT_FLEET = {"enabled": True, "enforcement": "block", "defaultTtlMinutes": 240}
# Upper bound on any lease TTL. Unbounded values overflow datetime arithmetic
# (`anchor + timedelta(minutes=ttl)` raises OverflowError above ~4.19e9 minutes),
# which escapes lease_is_live and aborts the whole conflict scan -- so ONE absurd
# lease stops every other live lease from being enforced. One year is far beyond
# any real working-set claim and leaves ~7 orders of magnitude of headroom.
FLEET_MAX_TTL_MINUTES = 60 * 24 * 365


def fleet_config(data: dict) -> dict:
    raw = data.get("fleet") if isinstance(data, dict) else None
    if raw is not None and not isinstance(raw, dict):
        raise SystemExit("Project adapter fleet must be an object")
    cfg = {**DEFAULT_FLEET, **(raw or {})}
    if not isinstance(cfg.get("enabled"), bool):
        raise SystemExit("Project adapter fleet.enabled must be a boolean")
    if cfg.get("enforcement") not in FLEET_ENFORCEMENT_CHOICES:
        raise SystemExit(
            "Project adapter fleet.enforcement must be one of: "
            + ", ".join(FLEET_ENFORCEMENT_CHOICES)
        )
    ttl = cfg.get("defaultTtlMinutes")
    if (
        not isinstance(ttl, int)
        or isinstance(ttl, bool)
        or ttl <= 0
        or ttl > FLEET_MAX_TTL_MINUTES
    ):
        raise SystemExit(
            "Project adapter fleet.defaultTtlMinutes must be a positive integer "
            f"no greater than {FLEET_MAX_TTL_MINUTES}"
        )
    return cfg


def fleet_state_dir(target: Path) -> Path | None:
    common = run_git(target, ["rev-parse", "--git-common-dir"])
    if not common or common == "unavailable":
        return None
    common_path = Path(common)
    if not common_path.is_absolute():
        common_path = (Path(target).resolve() / common_path).resolve()
    return common_path / "tautline-fleet"


def fleet_log_append(target: Path, event: dict) -> None:
    try:
        state = fleet_state_dir(target)
        if state is None:
            return
        state.mkdir(parents=True, exist_ok=True)
        record = {"ts": utc_event_timestamp(), **event}
        with (state / "fleet.log").open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, sort_keys=True) + "\n")
    except Exception:
        return


def fleet_parse_utc(value: str) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed


def lease_is_live(lease: dict, now: datetime) -> bool:
    anchor = fleet_parse_utc(lease.get("renewed_at") or lease.get("claimed_at") or "")
    ttl = lease.get("ttl_minutes")
    if anchor is None or not isinstance(ttl, int) or isinstance(ttl, bool) or ttl <= 0:
        return False
    if ttl > FLEET_MAX_TTL_MINUTES:
        return False
    try:
        return now <= anchor + timedelta(minutes=ttl)
    except OverflowError:
        # Belt and braces with the bound above: this predicate reads file-supplied
        # data, so it must be TOTAL for the same reason load_fleet_leases is. An
        # escaping raise here aborts the caller's entire conflict scan.
        return False


@contextmanager
def fleet_claims_lock(state: Path):
    """Exclusive claim lock that REPORTS whether it actually locked.

    Deliberately NOT advisory_flock(): that helper is best-effort by contract and
    degrades to running the body unlocked in BOTH failure modes -- fcntl missing
    (non-POSIX) *and* flock() raising OSError -- without telling the caller. Fleet
    must know the difference, because an unserialized claim has to warn and log
    rather than quietly present itself as atomic. Checking `import fcntl` alone is
    not enough: it misses the OSError path.

    Yields True when a real kernel lock is held, False when the body is running
    best-effort. Never raises on lock failure -- a coordination aid must not be
    the thing that stops a lane from working.
    """
    state.mkdir(parents=True, exist_ok=True)
    lock_path = state / "claims.lock"
    with lock_path.open("a", encoding="utf-8") as handle:
        try:
            import fcntl  # type: ignore[import-not-found]
        except ImportError:
            fcntl = None  # type: ignore[assignment]
        locked = False
        if fcntl is not None:
            try:
                fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
                locked = True
            except OSError:
                locked = False
        try:
            yield locked
        finally:
            if locked and fcntl is not None:
                try:
                    fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
                except OSError:
                    pass


def fleet_lease_well_formed(lease: dict) -> bool:
    # A lease may only ever BLOCK an edit if every field the guard reads is sane.
    # A schema-correct but malformed record (missing worktree_path, non-list
    # globs, bad ttl) would otherwise resolve to garbage identity -- e.g. an
    # absent worktree_path resolves to the process CWD -- and could block on it.
    # Fail-open means such a record is treated as stale, exactly like corruption.
    #
    # lease_id is interpolated into the escape COMMANDS the guard prints, so it is
    # untrusted input from a file any process can write. Pin it to the generated
    # shape (fleet_new_lease_id -> uuid4().hex[:12]) instead of "non-blank": a
    # corrupt lease carrying shell metacharacters must fail open as malformed, not
    # reach a command string.
    lease_id = lease.get("lease_id")
    if not isinstance(lease_id, str) or not re.fullmatch(r"[0-9a-f]{6,32}", lease_id):
        return False
    # worktree_path must be absolute: identity comparison resolves it, and a
    # relative value silently resolves against the CURRENT process CWD, making a
    # foreign lease look owned (or vice versa).
    worktree = lease.get("worktree_path")
    if not isinstance(worktree, str) or not worktree.strip():
        return False
    if "\x00" in worktree:
        # Path.resolve() raises ValueError on an embedded NUL. Identity comparison
        # resolves this value, so a NUL would escape as a raise from the conflict
        # scan rather than being treated as the malformed record it is.
        return False
    try:
        candidate = Path(worktree)
        if not candidate.is_absolute():
            return False
        # is_absolute() is NOT sufficient: every conflict scan calls .resolve() on
        # this value, and an absolute path through a symlink loop resolves with
        # OSError(ELOOP). That escape reaches the hook's top-level fail-open and
        # abandons the scan, so ONE bad lease stops every valid lease being
        # enforced. Do the resolve HERE, where failure means "malformed" -- the
        # same reasoning that made load_fleet_leases total.
        candidate.resolve()
    except (ValueError, OSError, RuntimeError):
        return False
    globs = lease.get("globs")
    if not isinstance(globs, list) or not globs:
        return False
    # EVERY entry must be a usable string, not merely one of them. Accepting
    # ["src/**", 7] lets the record load, and the claim/takeover conflict
    # reporting paths then do `','.join(globs)` and raise TypeError -- a CRASH on
    # corrupt local lease state, which is exactly what the fail-open contract
    # forbids. Lease files are local state any process can edit, so this is
    # reachable without a hostile actor.
    if not all(isinstance(item, str) and item.strip() for item in globs):
        return False
    ttl = lease.get("ttl_minutes")
    if not isinstance(ttl, int) or isinstance(ttl, bool) or ttl <= 0:
        return False
    if ttl > FLEET_MAX_TTL_MINUTES:
        return False
    anchor = lease.get("renewed_at") or lease.get("claimed_at") or ""
    return fleet_parse_utc(anchor) is not None


def load_fleet_leases(target: Path) -> list[dict]:
    state = fleet_state_dir(target)
    if state is None:
        return []
    leases_dir = state / "leases"
    if not leases_dir.is_dir():
        return []
    # The directory listing is a SNAPSHOT. A concurrent takeover publishes the
    # replacement and then unlinks the original, so a reader that globbed before
    # the publish and read after the unlink sees NEITHER -- and allows an edit a
    # live foreign lease covers. Write-then-delete fixes the filesystem ordering
    # but cannot fix a stale listing. So: if any lease vanishes mid-read, the
    # snapshot raced a mutation; re-glob once and redo. One retry is enough --
    # the second pass is taken after the publish is already visible.
    for attempt in (0, 1):
        leases, vanished = _load_fleet_leases_once(target, leases_dir)
        if not vanished or attempt == 1:
            return leases
    return leases


def _load_fleet_leases_once(target: Path, leases_dir: Path) -> tuple[list[dict], bool]:
    leases: list[dict] = []
    vanished = False
    for path in sorted(leases_dir.glob("*.json")):
        try:
            lease = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            # Raced a concurrent release/takeover; not corruption. Signal a retry
            # rather than logging a bogus corrupt-lease event.
            vanished = True
            continue
        except (OSError, ValueError, RecursionError):
            # ValueError covers BOTH json.JSONDecodeError and UnicodeDecodeError:
            # a lease file holding invalid UTF-8 must be skipped, not raised, or
            # the "never raised" fail-open contract breaks on undecodable bytes.
            # RecursionError is NOT a ValueError -- json.loads raises it on deeply
            # nested input -- and an escaping raise here would abandon every lease
            # sorting after the bad file, silently un-enforcing them.
            fleet_log_append(
                target,
                {
                    "event": "lease_expired_observed",
                    "lease_file": path.name,
                    "detail": "unreadable or corrupt lease treated as stale",
                },
            )
            continue
        if not isinstance(lease, dict) or lease.get("schema") != FLEET_LEASE_SCHEMA:
            fleet_log_append(
                target,
                {
                    "event": "lease_expired_observed",
                    "lease_file": path.name,
                    "detail": "unknown schema treated as stale",
                },
            )
            continue
        if not fleet_lease_well_formed(lease):
            fleet_log_append(
                target,
                {
                    "event": "lease_expired_observed",
                    "lease_file": path.name,
                    "detail": "malformed lease record treated as stale",
                },
            )
            continue
        lease["_path"] = str(path)
        leases.append(lease)
    return leases, vanished


def write_fleet_lease(target: Path, lease: dict) -> Path:
    # Published atomically, fully-formed, in ONE step. The guard reads leases/
    # WITHOUT taking the claims lock, so a lease file must never be observable in
    # a partial state: a reader that caught an empty or half-written file would
    # classify it malformed, treat it as stale, and ALLOW an edit that should
    # have been blocked.
    #
    # os.link() does both jobs at once: it is atomic, and it fails with
    # FileExistsError if the destination exists -- the same id-uniqueness
    # guarantee a direct O_CREAT|O_EXCL create gave, but on a file whose content
    # is already complete and fsynced. The temp name is dot-prefixed so the
    # loader's leases_dir.glob("*.json") never sees it.
    state = fleet_state_dir(target)
    if state is None:
        raise SystemExit("fleet: not inside a git checkout; no fleet state dir")
    leases_dir = state / "leases"
    leases_dir.mkdir(parents=True, exist_ok=True)
    path = leases_dir / f"{lease['lease_id']}.json"
    payload = json.dumps(lease, indent=2, sort_keys=True) + "\n"
    tmp = leases_dir / f".{lease['lease_id']}.{os.getpid()}.tmp"
    try:
        fd = os.open(tmp, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.link(tmp, path)  # atomic publish; FileExistsError on id collision
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass
    return path


def _fleet_glob_to_regex(glob_text: str) -> str:
    # A trailing "/**" also matches the bare directory itself: "src/**" covers
    # "src" as well as everything under it (regex tail becomes "(/.*)?").
    text = glob_text
    dir_suffix = False
    if text.endswith("/**"):
        text = text[:-3]
        dir_suffix = True
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == "*":
            if text[i : i + 2] == "**":
                i += 2
                if i < len(text) and text[i] == "/":
                    # "a/**/b" spans zero or more WHOLE segments, so the emitted
                    # group must keep the separator. Emitting a bare ".*" here
                    # compiles "src/**/a.py" to "^src/.*a\.py$", which matches
                    # "src/fooa.py" -- an over-block on a path the lease never
                    # covered, contradicting "the guard never over-blocks".
                    out.append("(?:.*/)?")
                    i += 1
                else:
                    out.append(".*")
                continue
            out.append("[^/]*")
        elif ch == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(ch))
        i += 1
    body = "".join(out)
    if dir_suffix:
        return "^" + body + "(/.*)?$"
    return "^" + body + "$"


def fleet_normalize_glob(glob_text: str) -> str:
    # Repo-root-relative form. A "./"-prefixed glob would otherwise claim happily
    # and then guard nothing (the matcher compares against paths with no "./"),
    # and would not even collide with its own bare equivalent at claim time.
    text = str(glob_text).strip().replace(os.sep, "/").lstrip("/")
    while text.startswith("./"):
        text = text[2:]
    return text


def fleet_globs_match(rel_path: str, globs: list) -> bool:
    posix = str(rel_path).replace(os.sep, "/").lstrip("/")
    for glob_text in globs or []:
        if not isinstance(glob_text, str) or not glob_text.strip():
            continue
        pattern = _fleet_glob_to_regex(fleet_normalize_glob(glob_text))
        if re.match(pattern, posix):
            return True
    return False


def _fleet_seg_tokens_overlap(seg_a: str, seg_b: str) -> bool:
    # Within ONE segment: a wildcard is assumed to overlap the opposing segment
    # (deliberate over-approximation -- claims warn/block conservatively, and the
    # edit-time guard matches real paths so it never over-blocks an actual edit).
    if ("*" in seg_a or "?" in seg_a) or ("*" in seg_b or "?" in seg_b):
        return True
    return seg_a == seg_b


def _fleet_segments_overlap(segs_a: list[str], segs_b: list[str]) -> bool:
    """Can ANY concrete path match both segment patterns?

    A `**` segment absorbs zero or more WHOLE segments, so it cannot simply
    short-circuit to True: `src/**/a.py` and `src/b.py` share a `**` yet no path
    matches both, and returning True there rejects a legitimately disjoint
    narrowed claim -- which breaks the guard's own first escape ("narrow the edit
    outside the leased globs"). Instead the `**` is tried against every possible
    absorption length and the REMAINING segments must still align.
    """
    if not segs_a and not segs_b:
        return True
    if not segs_a or not segs_b:
        return False
    head_a, head_b = segs_a[0], segs_b[0]
    if "**" in head_a:
        return any(
            _fleet_segments_overlap(segs_a[1:], segs_b[i:])
            for i in range(len(segs_b) + 1)
        )
    if "**" in head_b:
        return any(
            _fleet_segments_overlap(segs_a[i:], segs_b[1:])
            for i in range(len(segs_a) + 1)
        )
    if not _fleet_seg_tokens_overlap(head_a, head_b):
        return False
    return _fleet_segments_overlap(segs_a[1:], segs_b[1:])


def fleet_glob_pair_overlap(glob_a: str, glob_b: str) -> bool:
    segs_a = [s for s in fleet_normalize_glob(glob_a).strip("/").split("/") if s]
    segs_b = [s for s in fleet_normalize_glob(glob_b).strip("/").split("/") if s]
    if not segs_a or not segs_b:
        return False
    # A trailing "/**" also covers the bare directory, mirroring the matcher.
    if segs_a[-1] == "**" and _fleet_segments_overlap(segs_a[:-1], segs_b):
        return True
    if segs_b[-1] == "**" and _fleet_segments_overlap(segs_a, segs_b[:-1]):
        return True
    return _fleet_segments_overlap(segs_a, segs_b)


def fleet_glob_sets_overlap(globs_a: list, globs_b: list) -> tuple[str, str] | None:
    for ga in globs_a or []:
        if not isinstance(ga, str) or not ga.strip():
            continue
        for gb in globs_b or []:
            if not isinstance(gb, str) or not gb.strip():
                continue
            if fleet_glob_pair_overlap(ga, gb):
                return (ga, gb)
    return None


def fleet_conflicting_lease(
    target: Path, rel_path: str, own_worktree: Path | None, now: datetime
) -> dict | None:
    own_resolved = (
        str(Path(own_worktree).resolve()) if own_worktree is not None else None
    )
    for lease in load_fleet_leases(target):
        holder = str(Path(str(lease.get("worktree_path") or "")).resolve())
        if own_resolved is not None and holder == own_resolved:
            continue
        if not lease_is_live(lease, now):
            continue
        if fleet_globs_match(rel_path, lease.get("globs") or []):
            return lease
    return None


def fleet_current_worktree(target: Path) -> Path | None:
    top = run_git(target, ["rev-parse", "--show-toplevel"])
    if not top or top == "unavailable":
        return None
    return Path(top)


def fleet_new_lease_id() -> str:
    return uuid.uuid4().hex[:12]


def _fleet_load_context(args: argparse.Namespace) -> tuple[dict, Path, Path]:
    target = Path(getattr(args, "target", Path("."))).resolve()
    root = find_adapter_root(target)
    if root is None:
        raise SystemExit("fleet: no adapter marker (.tautline.json) found above target")
    data = load_project(adapter_marker_path(root))
    worktree = fleet_current_worktree(target)
    if worktree is None:
        raise SystemExit("fleet: not inside a git checkout")
    return data, root, worktree


def fleet_claim(
    data: dict, worktree: Path, globs: list, ttl_minutes: int | None,
    goal: str | None, note: str | None, adapter_root: Path | None = None,
) -> tuple[int, list[str]]:
    cfg = fleet_config(data)
    if not cfg["enabled"]:
        return 0, ["fleet_lease: disabled by adapter (fleet.enabled=false)"]
    if not globs:
        raise SystemExit("fleet-lease claim requires --globs g1,g2,...")
    ttl = cfg["defaultTtlMinutes"]
    if ttl_minutes is not None:
        if ttl_minutes <= 0 or ttl_minutes > FLEET_MAX_TTL_MINUTES:
            raise SystemExit(
                "fleet-lease: --ttl-minutes must be a positive integer no greater "
                f"than {FLEET_MAX_TTL_MINUTES}"
            )
        ttl = ttl_minutes
    state = fleet_state_dir(worktree)
    if state is None:
        raise SystemExit("fleet: not inside a git checkout; no fleet state dir")
    state.mkdir(parents=True, exist_ok=True)
    now = datetime.now(timezone.utc)
    own = str(worktree.resolve())
    lines: list[str] = []
    # Critical section: the conflict scan and the lease create must be atomic
    # TOGETHER -- two lanes racing on overlapping globs would otherwise both
    # scan an empty store and both win. fleet_claims_lock serializes them and,
    # unlike advisory_flock, reports when it could not actually lock.
    with fleet_claims_lock(state) as locked:
        if not locked:
            # Honest degradation, not a silent one: the caller learns the claim
            # was not serialized, and the evidence trail records it. Reported
            # from INSIDE the lock helper, so it covers the flock-raised-OSError
            # case too, not merely a missing fcntl module.
            lines.append(
                "fleet_lease_warn: advisory locking unavailable on this host; the "
                "claim is best-effort and concurrent overlapping claims may both "
                "succeed"
            )
            fleet_log_append(
                worktree, {"event": "lease_claim_unserialized", "claimant": own}
            )
        conflict = None
        for entry in load_fleet_leases(worktree):
            holder = str(Path(str(entry.get("worktree_path") or "")).resolve())
            if holder == own or not lease_is_live(entry, now):
                continue
            if fleet_glob_sets_overlap(globs, entry.get("globs") or []) is not None:
                conflict = entry
                break
        if conflict is not None:
            lines.append(
                "fleet_lease_conflict: "
                f"{conflict.get('lease_id')} holder={conflict.get('worktree_path')} "
                f"globs={','.join(str(g) for g in conflict.get('globs') or [])}"
            )
            fleet_log_append(
                worktree,
                {
                    "event": "lease_conflict_observed",
                    "claimant": own,
                    "holder_lease": conflict.get("lease_id"),
                    "globs": globs,
                    "enforcement": cfg["enforcement"],
                },
            )
            if cfg["enforcement"] == "block":
                # Same runnability contract as the guard's escapes: --target (the
                # claim may be driven with --target from another cwd, so a bare
                # command would act on the caller's repo) and --operator-note (the
                # conflicting lease is live and foreign, so both paths are
                # operator-owned and refuse without it). shlex.quote for paths
                # containing spaces or shell metacharacters, and for the lease id,
                # which is read from a file.
                # The adapter root, NOT the git worktree root: when the marker
                # lives in a subdirectory (a supported monorepo/subproject layout
                # that _fleet_load_context accepts), find_adapter_root only walks
                # UP, so a worktree-root --target finds no marker and every printed
                # escape exits 1. Mirrors the guard path's offset handling.
                quoted = shlex.quote(str(adapter_root or worktree))
                conflict_id = shlex.quote(str(conflict.get("lease_id")))
                lines.append(
                    "fleet_lease_instruction: narrow --globs, or use "
                    f"`tautline fleet-lease takeover --target {quoted} "
                    f"--lease {conflict_id} --note \"<why>\" "
                    "--operator-note \"<operator's decision>\"`, or ask the operator "
                    f"to run `tautline fleet-lease release --target {quoted} "
                    f"--lease {conflict_id} --operator-note \"<operator's decision>\"`."
                )
                return 1, lines
        new_lease = {
            "schema": FLEET_LEASE_SCHEMA,
            "lease_id": fleet_new_lease_id(),
            "worktree_path": str(worktree),
            "branch": run_git(worktree, ["rev-parse", "--abbrev-ref", "HEAD"]),
            "goal_ref": goal or "",
            "globs": globs,
            "claimed_at": now.isoformat(),
            "renewed_at": now.isoformat(),
            "ttl_minutes": int(ttl),
            "session": {
                "pid": os.getpid(),
                "host": socket.gethostname(),
                "started_at": now.isoformat(),
            },
            "note": note or "",
        }
        write_fleet_lease(worktree, new_lease)
    fleet_log_append(
        worktree,
        {
            "event": "lease_claimed",
            "lease_id": new_lease["lease_id"],
            "worktree": own,
            "globs": globs,
        },
    )
    lines.append(
        f"fleet_lease: claimed {new_lease['lease_id']} globs={len(globs)} "
        f"ttl={new_lease['ttl_minutes']}m"
    )
    return 0, lines


def fleet_warn_unserialized(worktree: Path, action: str, locked: bool) -> None:
    """Say so when a lease MUTATION ran without a real lock.

    fleet_claims_lock yields False when fcntl is missing or flock() fails, and the
    body still runs -- deliberately, because a coordination aid must not stop a
    lane from working. But a mutation that reports success while the serialization
    it depends on did not hold is a silent lie: concurrent claims/takeovers can
    leave duplicate overlapping leases. Every mutation path routes through here so
    none of them can quietly skip it.
    """
    if locked:
        return
    print(
        f"fleet_lease_warn: advisory locking unavailable on this host; {action} ran "
        "best-effort and concurrent lease mutations may interleave"
    )
    fleet_log_append(
        worktree,
        {"event": "lease_mutation_unserialized", "action": action,
         "worktree": str(worktree.resolve())},
    )


def fleet_lease_command(args: argparse.Namespace) -> int:
    data, root, worktree = _fleet_load_context(args)
    cfg = fleet_config(data)
    if not cfg["enabled"]:
        print("fleet_lease: disabled by adapter (fleet.enabled=false)")
        return 0
    now = datetime.now(timezone.utc)
    action = args.action

    if action == "claim":
        globs = [g.strip() for g in (args.globs or "").split(",") if g.strip()]
        code, lines = fleet_claim(
            data, worktree, globs, args.ttl_minutes, args.goal, args.note,
            adapter_root=root,
        )
        for line in lines:
            print(line)
        return code

    if action in ("renew", "release"):
        state = fleet_state_dir(worktree)
        if state is None:
            raise SystemExit("fleet: not inside a git checkout; no fleet state dir")
        state.mkdir(parents=True, exist_ok=True)
        # Renew/release mutate lease files, so they need the SAME critical
        # section as claim/takeover: a renew racing a takeover would otherwise
        # atomically re-create the old lease file after takeover deleted it,
        # resurrecting a second live overlapping lease. Targets are re-loaded
        # INSIDE the lock -- pre-lock `_path`s may already be gone.
        with fleet_claims_lock(state) as locked:
            fleet_warn_unserialized(worktree, action, locked)
            own = str(worktree.resolve())
            leases_now = load_fleet_leases(worktree)
            if args.lease:
                targets = [
                    entry for entry in leases_now
                    if entry.get("lease_id") == args.lease
                ]
                if not targets:
                    raise SystemExit(f"fleet-lease: no lease with id {args.lease}")
                holder = str(Path(str(targets[0].get("worktree_path") or "")).resolve())
                if holder != own and not args.operator_note:
                    raise SystemExit(
                        "fleet-lease: acting on another lane's lease requires "
                        "--operator-note"
                    )
            else:
                targets = [
                    entry for entry in leases_now
                    if str(Path(str(entry.get("worktree_path") or "")).resolve()) == own
                ]
            if not targets:
                print("fleet_lease: no owned leases")
                return 0
            live_now = [entry for entry in leases_now if lease_is_live(entry, now)]
            for lease in targets:
                path = Path(lease["_path"])
                if action == "renew":
                    # A renew that REVIVES a stale lease must re-scan for conflicts.
                    # While this lease was lapsed another lane could legitimately
                    # claim its globs (claim ignores stale records), so blindly
                    # refreshing renewed_at yields TWO live overlapping leases and
                    # both lanes then block each other -- a mutual deadlock, which
                    # is strictly worse than the missed-block direction everything
                    # else here fails toward. Live leases skip this: renewing an
                    # already-live lease cannot introduce a conflict that the
                    # original claim did not already clear.
                    if not lease_is_live(lease, now):
                        revived = None
                        for other in live_now:
                            holder = str(
                                Path(str(other.get("worktree_path") or "")).resolve()
                            )
                            if holder == own:
                                continue
                            if fleet_glob_sets_overlap(
                                lease.get("globs") or [], other.get("globs") or []
                            ) is not None:
                                revived = other
                                break
                        if revived is not None:
                            print(
                                "fleet_lease_conflict: "
                                f"{revived.get('lease_id')} "
                                f"holder={revived.get('worktree_path')} "
                                f"globs={','.join(str(g) for g in revived.get('globs') or [])}"
                            )
                            fleet_log_append(
                                worktree,
                                {"event": "lease_conflict_observed", "claimant": own,
                                 "holder_lease": revived.get("lease_id"),
                                 "during": "renew-revive",
                                 "enforcement": cfg["enforcement"]},
                            )
                            if cfg["enforcement"] == "block":
                                print(
                                    "fleet_lease_instruction: this lease lapsed and its "
                                    "globs are now held by a live lane; claim a narrowed "
                                    "set, or take the lease over with an operator note."
                                )
                                return 1
                    lease_out = {k: v for k, v in lease.items() if k != "_path"}
                    lease_out["renewed_at"] = now.isoformat()
                    write_text_atomic(
                        path, json.dumps(lease_out, indent=2, sort_keys=True) + "\n"
                    )
                    fleet_log_append(
                        worktree,
                        {"event": "lease_renewed", "lease_id": lease["lease_id"]},
                    )
                    print(f"fleet_lease: renewed {lease['lease_id']}")
                else:
                    path.unlink(missing_ok=True)
                    fleet_log_append(
                        worktree,
                        {
                            "event": "lease_released",
                            "lease_id": lease["lease_id"],
                            "operator_note": args.operator_note or "",
                        },
                    )
                    print(f"fleet_lease: released {lease['lease_id']}")
        return 0

    # takeover
    if not args.lease:
        raise SystemExit("fleet-lease takeover requires --lease <id>")
    if not args.note:
        raise SystemExit("fleet-lease takeover requires --note <why>")
    state = fleet_state_dir(worktree)
    if state is None:
        raise SystemExit("fleet: not inside a git checkout; no fleet state dir")
    state.mkdir(parents=True, exist_ok=True)
    # EVERYTHING happens inside the critical section: load, liveness gating,
    # conflict re-scan, publish, delete. Loading before the lock races a
    # concurrent claim -- a lease observed stale pre-lock can be superseded by a
    # fresh overlapping claim, and a blind delete+recreate would then leave two
    # live overlapping leases even under block enforcement.
    with fleet_claims_lock(state) as locked:
        fleet_warn_unserialized(worktree, "takeover", locked)
        matches = [
            entry for entry in load_fleet_leases(worktree)
            if entry.get("lease_id") == args.lease
        ]
        if not matches:
            raise SystemExit(f"fleet-lease: no lease with id {args.lease}")
        lease = matches[0]
        live = lease_is_live(lease, now)
        if live and not args.operator_note:
            raise SystemExit(
                "fleet-lease: takeover of a LIVE lease is operator-owned; pass "
                "--operator-note with the operator's decision (stale leases need "
                "only --note)"
            )
        own = str(worktree.resolve())
        for other in load_fleet_leases(worktree):
            if other.get("lease_id") == args.lease:
                continue
            holder = str(Path(str(other.get("worktree_path") or "")).resolve())
            if holder == own or not lease_is_live(other, now):
                continue
            if fleet_glob_sets_overlap(
                lease.get("globs") or [], other.get("globs") or []
            ) is not None:
                # Enforcement-aware, exactly like fleet_claim: under advise/observe
                # a FRESH claim for these globs would be allowed, so refusing the
                # takeover would make takeover stricter than claim in projects that
                # deliberately chose a non-blocking posture.
                if cfg["enforcement"] != "block":
                    print(
                        f"fleet_lease_conflict: {other.get('lease_id')} "
                        f"holder={other.get('worktree_path')} "
                        f"globs={','.join(str(g) for g in other.get('globs') or [])}"
                    )
                    fleet_log_append(
                        worktree,
                        {
                            "event": "lease_conflict_observed",
                            "claimant": own,
                            "holder_lease": other.get("lease_id"),
                            "during": "takeover",
                            "enforcement": cfg["enforcement"],
                        },
                    )
                    continue
                raise SystemExit(
                    f"fleet-lease: takeover refused; live lease "
                    f"{other.get('lease_id')} now covers overlapping globs — "
                    "claim a narrowed set instead"
                )
        taken = {k: v for k, v in lease.items() if k != "_path"}
        taken["lease_id"] = fleet_new_lease_id()
        taken["worktree_path"] = str(worktree)
        taken["branch"] = run_git(worktree, ["rev-parse", "--abbrev-ref", "HEAD"])
        taken["claimed_at"] = now.isoformat()
        taken["renewed_at"] = now.isoformat()
        taken["session"] = {
            "pid": os.getpid(),
            "host": socket.gethostname(),
            "started_at": now.isoformat(),
        }
        taken["note"] = args.note
        # Publish the replacement FIRST, then drop the original. Deleting first
        # opens a window in which NO lease covers these globs, and the guard --
        # which scans without the lock -- would allow a foreign edit straight
        # through it. Write-then-delete means a concurrent reader always sees at
        # least one of the two leases, never neither.
        write_fleet_lease(worktree, taken)
        Path(lease["_path"]).unlink(missing_ok=True)
    fleet_log_append(
        worktree,
        {
            "event": "lease_takeover",
            "from_lease": args.lease,
            "to_lease": taken["lease_id"],
            "was_live": live,
            "note": args.note,
            "operator_note": args.operator_note or "",
        },
    )
    print(
        f"fleet_lease: takeover {taken['lease_id']} "
        f"({'live-operator' if live else 'stale'})"
    )
    return 0


def fleet_guard_block_reason(
    data: dict, target: Path, cwd: Path, file_path: Path
) -> tuple[str | None, str | None]:
    cfg = fleet_config(data)
    if not cfg["enabled"]:
        return None, None
    repo_worktree = fleet_current_worktree(target)
    if repo_worktree is None:
        return None, None
    # Match against BOTH spellings of the edit path. resolve() stays because it is
    # load-bearing for cross-repo attribution and for the containment check that
    # keeps out-of-repo targets unguarded -- but a lease is stored against the
    # spelling its holder CLAIMED. When `link -> actual` inside the repo, a lease
    # on `link/**` never sees an edit to `link/a.py` if only the resolved
    # `actual/a.py` is matched, and a symlink pointing outside the repo makes
    # relative_to() fail and allows the edit outright. Checking the lexical
    # spelling as well closes both, and is purely additive: it can only ever add
    # a block that a lease already covers, never remove one.
    candidates: list[str] = []
    try:
        candidates.append(str(file_path.resolve().relative_to(repo_worktree.resolve())))
    except ValueError:
        pass
    try:
        lexical = Path(os.path.normpath(str(file_path)))
        lex_rel = str(lexical.relative_to(repo_worktree))
        if lex_rel not in candidates:
            candidates.append(lex_rel)
    except (ValueError, OSError):
        pass
    if not candidates:
        return None, None  # outside the governed repo root: never fleet-checked
    rel = candidates[0]
    leases = load_fleet_leases(repo_worktree)
    if not leases:
        return None, None  # fast path: no leases at all -- nothing to arbitrate
    # DELIBERATELY lock-free, and safe only because the writers cooperate.
    # Taking the claims lock here would put a blocking flock on the PreToolUse
    # path of every edit: one wedged claim process would hang every lane's
    # editor, which is a far worse failure than the collision the lock would
    # prevent, and it contradicts the fail-open contract outright.
    # The races a reader lock would close are instead closed on the WRITE side:
    #   - partial reads -> write_fleet_lease publishes atomically via os.link of
    #                      a fully-written, fsynced temp file
    #   - takeover gap  -> takeover writes the replacement BEFORE unlinking the
    #                      original, so a reader always sees one of them
    #   - renew         -> write_text_atomic (rename), never a partial file
    # Any change to those three call sites MUST preserve this property, or this
    # scan silently starts allowing edits it should block.
    #
    # The editor's lane identity: only a worktree of the SAME repo family owns
    # leases here; a cross-repo (or non-git) editor is foreign to every lease.
    editor_worktree = fleet_current_worktree(cwd)
    same_repo_editor = None
    if editor_worktree is not None:
        editor_state = fleet_state_dir(editor_worktree)
        repo_state = fleet_state_dir(repo_worktree)
        if (
            editor_state is not None
            and repo_state is not None
            and editor_state.resolve() == repo_state.resolve()
        ):
            same_repo_editor = editor_worktree
    now = datetime.now(timezone.utc)
    conflict = None
    for candidate in candidates:
        conflict = fleet_conflicting_lease(
            repo_worktree, candidate, same_repo_editor, now
        )
        if conflict is not None:
            rel = candidate
            break
    if conflict is None:
        return None, None
    anchor = fleet_parse_utc(
        conflict.get("renewed_at") or conflict.get("claimed_at") or ""
    )
    remaining = "unknown"
    if anchor is not None:
        ttl_minutes = int(conflict.get("ttl_minutes") or 0)
        delta = anchor + timedelta(minutes=ttl_minutes) - now
        remaining = f"{max(0, int(delta.total_seconds() // 60))}m"
    detail = (
        f"path {rel} is leased by lane {conflict.get('worktree_path')} "
        f"(branch {conflict.get('branch')}, goal {conflict.get('goal_ref') or 'unset'}, "
        f"lease {conflict.get('lease_id')}, ttl remaining {remaining})."
    )
    # Every escape carries --target. Two reasons:
    # (1) In the cross-repo cases (cwd outside any repo, or inside a DIFFERENT
    #     adapter-backed repo) a --target-less command resolves the wrong adapter
    #     root or none at all -- not runnable, which the three-runnable-escapes
    #     criterion forbids.
    # (2) Semantics: `takeover` grants the lease TO the --target worktree, so
    #     --target must name the BLOCKED lane, not the edit path's worktree. Those
    #     differ whenever a lane writes an absolute path into ANOTHER worktree of
    #     the same repo: there the edit path resolves to the HOLDER, and targeting
    #     it would re-grant the holder its own lease -- a no-op that leaves the
    #     blocked lane blocked forever, i.e. an escape that cannot escape.
    #     same_repo_editor is exactly "the editor's lane within this fleet", so it
    #     is the right target whenever it exists. It is None only when the editor
    #     has no lane identity here (cwd outside any repo, or a different repo
    #     family), and then the leased worktree is the best runnable fallback.
    #
    # Both escapes also carry --operator-note UNCONDITIONALLY. The guard blocks
    # ONLY on a live foreign lease, so by construction every escape printed here
    # hits the operator-owned path: takeover of a live lease refuses without it,
    # and so does a release of another lane's lease. Printing the ungated form
    # produced commands that always failed on first run -- "runnable escape"
    # means runnable as printed, with only the operator's own words to fill in.
    #
    # shlex.quote on the path AND the lease id: repo paths with spaces or shell
    # metacharacters would otherwise emit a command that word-splits into
    # something else, and the lease id is read from a file. Placeholders are
    # quoted too: a literal `--note <why>` copied into a shell is a redirection.
    escape_target = same_repo_editor if same_repo_editor is not None else repo_worktree
    # --target must be a path from which BOTH the adapter marker is findable
    # (find_adapter_root only walks UP) and the intended worktree resolves. When the
    # marker sits in a SUBDIRECTORY -- a monorepo/subproject layout find_adapter_root
    # supports and `claim` accepts -- a bare worktree root finds no marker and every
    # printed escape exits 1. Carry the marker's position within the worktree across.
    try:
        adapter_offset = Path(target).resolve().relative_to(repo_worktree.resolve())
    except ValueError:
        adapter_offset = Path(".")
    if str(adapter_offset) != ".":
        escape_target = escape_target / adapter_offset
    quoted_target = shlex.quote(str(escape_target))
    quoted_lease = shlex.quote(str(conflict.get("lease_id")))
    escapes = (
        " Escapes: (1) narrow the edit outside the leased globs; "
        f"(2) `tautline fleet-lease takeover --target {quoted_target} "
        f"--lease {quoted_lease} --note \"<why>\" "
        "--operator-note \"<operator's decision>\"` — taking a LIVE lease is "
        "operator-owned, so the note must carry the operator's actual decision; "
        f"(3) ask the operator to run `tautline fleet-lease release --target "
        f"{quoted_target} --lease {quoted_lease} "
        "--operator-note \"<operator's decision>\"`."
    )
    if cfg["enforcement"] == "block":
        return "fleet: " + detail + escapes, None
    if cfg["enforcement"] == "advise":
        return None, "fleet: " + detail + escapes
    fleet_log_append(
        repo_worktree,
        {
            "event": "edit_would_block",
            "path": str(rel),
            "holder_lease": conflict.get("lease_id"),
            "editor_worktree": str(editor_worktree) if editor_worktree else str(cwd),
        },
    )
    return None, None


def fleet_guard_hook(args: argparse.Namespace) -> int:
    try:
        payload = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0
    tool_name = str(payload.get("tool_name") or "")
    if tool_name not in ("Edit", "Write", "MultiEdit", "NotebookEdit"):
        return 0
    tool_input = payload.get("tool_input") or {}
    file_path_raw = None
    if isinstance(tool_input, dict):
        file_path_raw = tool_input.get("file_path") or tool_input.get("notebook_path")
    if not file_path_raw:
        return 0
    cwd = Path(payload.get("cwd") or ".").expanduser().resolve(strict=False)
    edit_path = Path(str(file_path_raw)).expanduser()
    if not edit_path.is_absolute():
        edit_path = cwd / edit_path
    # The governed repo is the EDIT PATH's repo, not cwd's: a session working in
    # adapter-backed repo A can write an absolute path into leased repo B, and
    # the lease store consulted must be B's. cwd is only the last fallback.
    #
    # Both spellings are tried, for the same reason fleet_guard_block_reason
    # matches both: when the path is lexically inside the leased repo via a
    # symlink whose target lies OUTSIDE that repo (or in another one), resolving
    # first hides the repo that actually owns the lease, and the cwd fallback
    # then consults no repo or the wrong one -- so a lease on `link/**` is
    # bypassed for an edit to `<repo>/link/file`. Attribution and matching must
    # agree, or fixing one layer just moves the bypass to the other.
    target = None
    for candidate in (
        edit_path.parent.resolve(strict=False),
        Path(os.path.normpath(str(edit_path.parent))),
        cwd,
    ):
        target = find_adapter_root(candidate)
        if target is not None:
            break
    if target is None:
        return 0
    try:
        data = load_project(adapter_marker_path(target))
    except SystemExit:
        return 0
    try:
        reason, context = fleet_guard_block_reason(data, target, cwd, edit_path)
    except SystemExit:
        return 0  # malformed fleet adapter config must not wedge edits
    # fleet.log is the spec's evidence surface and it names edit_blocked and
    # edit_advised alongside edit_would_block. Logging only guard_log_event here
    # would leave block/advise projects with NO fleet.log record of the very
    # decisions they enforce -- observe-mode repos would have a richer audit
    # trail than blocking ones. Both surfaces get written.
    repo_worktree = fleet_current_worktree(target)
    if reason is not None:
        guard_log_event(target, "fleet.edit_lease", True, "state", reason[:200])
        if repo_worktree is not None:
            fleet_log_append(
                repo_worktree,
                {
                    "event": "edit_blocked",
                    "path": str(edit_path),
                    "editor_cwd": str(cwd),
                    "detail": reason[:200],
                },
            )
        hook_decision(reason)
    elif context is not None:
        guard_log_event(target, "fleet.edit_lease", False, "state", "advised")
        if repo_worktree is not None:
            fleet_log_append(
                repo_worktree,
                {
                    "event": "edit_advised",
                    "path": str(edit_path),
                    "editor_cwd": str(cwd),
                    "detail": context[:200],
                },
            )
        hook_additional_context("PreToolUse", context)
    return 0

DEFAULT_CLAUDE_AUTOCOMPACT_PERCENT = 85
